#!/usr/bin/env python3
"""Fill training_feedback_template.hwpx using training_feedback.json.

Outputs: /root/training_feedback_ready.hwpx

Notes:
- HWPX is a ZIP; we extract, replace placeholders in XML, remove layout cache nodes
  in modified paragraphs/runs, then re-zip.
"""

from __future__ import annotations

import json
import re
import shutil
import tempfile
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET

SRC_HWPX = Path("/root/training_feedback_template.hwpx")
SRC_JSON = Path("/root/training_feedback.json")
OUT_HWPX = Path("/root/training_feedback_ready.hwpx")

HP_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"


def _localname(tag: str) -> str:
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def _build_replacements(data: dict) -> dict[str, str]:
    # start with direct stringification
    rep: dict[str, str] = {k: "" if v is None else str(v) for k, v in data.items()}

    # 참석자수: digits only
    if "참석자수" in rep:
        rep["참석자수"] = re.sub(r"\D+", "", rep["참석자수"])

    # 만족도: X.X점 (5.0점 만점)
    raw_sat = data.get("만족도")
    score_str: str | None = None
    if isinstance(raw_sat, (int, float)):
        score_str = str(raw_sat)
    elif raw_sat is not None:
        m = re.search(r"([0-9]+(?:\.[0-9]+)?)", str(raw_sat))
        if m:
            score_str = m.group(1)

    rep["만족도"] = f"{score_str if score_str is not None else ''}점 (5.0점 만점)"

    # 종합의견: append sentence
    suffix = "후속 심화반 검토 요망."
    opinion = str(data.get("종합의견") or "")
    if opinion.rstrip().endswith(suffix):
        rep["종합의견"] = opinion
    else:
        sep = "" if (not opinion) or opinion.endswith((" ", "\t", "\n")) else " "
        rep["종합의견"] = f"{opinion}{sep}{suffix}" if opinion else suffix

    return rep


def _replace_placeholders(text: str, rep: dict[str, str]) -> str:
    # Replace all {{키}} patterns in the given text.
    def _sub(m: re.Match) -> str:
        key = m.group(1).strip()
        if key not in rep:
            raise KeyError(f"Unknown placeholder: {key}")
        return rep[key]

    return re.sub(r"\{\{([^}]+)\}\}", _sub, text)


def _remove_layout_cache_within(ancestor: ET.Element, parent_map: dict[ET.Element, ET.Element]) -> int:
    removed = 0
    # Iterate over a snapshot list to allow removals
    for node in list(ancestor.iter()):
        if _localname(node.tag) in ("layoutCache", "lc"):
            parent = parent_map.get(node)
            if parent is not None:
                parent.remove(node)
                removed += 1
    return removed


def _process_xml(xml_path: Path, rep: dict[str, str]) -> None:
    raw = xml_path.read_bytes()
    root = ET.fromstring(raw)

    parent_map: dict[ET.Element, ET.Element] = {}
    for parent in root.iter():
        for child in list(parent):
            parent_map[child] = parent

    modified_runs: set[ET.Element] = set()
    modified_ps: set[ET.Element] = set()

    for el in root.iter():
        if _localname(el.tag) != "t":
            continue
        t = el.text or ""
        if "{{" not in t:
            continue

        new_t = _replace_placeholders(t, rep)
        if new_t != t:
            el.text = new_t

            # climb to find enclosing run and p
            cur = el
            run_anc = None
            p_anc = None
            while cur in parent_map:
                cur = parent_map[cur]
                ln = _localname(cur.tag)
                if run_anc is None and ln == "run":
                    run_anc = cur
                if p_anc is None and ln == "p":
                    p_anc = cur
                if run_anc is not None and p_anc is not None:
                    break

            if run_anc is not None:
                modified_runs.add(run_anc)
            if p_anc is not None:
                modified_ps.add(p_anc)

    # Remove layout cache nodes within modified run or paragraph
    for run in modified_runs:
        _remove_layout_cache_within(run, parent_map)
    for p in modified_ps:
        _remove_layout_cache_within(p, parent_map)

    ET.ElementTree(root).write(xml_path, encoding="utf-8", xml_declaration=True)


def main() -> None:
    data = json.loads(SRC_JSON.read_text(encoding="utf-8"))
    rep = _build_replacements(data)

    tmpdir = Path(tempfile.mkdtemp(prefix="hwpx_fill_"))
    try:
        # 1) Extract
        with zipfile.ZipFile(SRC_HWPX, "r") as z:
            z.extractall(tmpdir)

        # 2) Replace placeholders in all XML files
        for p in sorted(tmpdir.rglob("*.xml")):
            _process_xml(p, rep)

        # 3) For any other text files containing {{...}}, do plain substitution
        for p in sorted(tmpdir.rglob("*")):
            if not p.is_file() or p.suffix.lower() == ".xml":
                continue
            try:
                txt = p.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                continue
            if "{{" not in txt:
                continue
            p.write_text(_replace_placeholders(txt, rep), encoding="utf-8")

        # 4) Verify no placeholders remain anywhere
        leftovers = []
        for p in sorted(tmpdir.rglob("*")):
            if not p.is_file():
                continue
            try:
                b = p.read_bytes()
            except OSError:
                continue
            if b.find(b"{{") != -1:
                leftovers.append(str(p.relative_to(tmpdir)))
        if leftovers:
            raise RuntimeError(f"Unreplaced placeholders remain in: {leftovers}")

        # 5) Re-zip
        if OUT_HWPX.exists():
            OUT_HWPX.unlink()
        with zipfile.ZipFile(OUT_HWPX, "w", compression=zipfile.ZIP_DEFLATED) as z:
            for p in sorted(tmpdir.rglob("*")):
                if p.is_file():
                    z.write(p, arcname=str(p.relative_to(tmpdir)))

    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)


if __name__ == "__main__":
    main()

